import{n as e}from"./rolldown-runtime-Cyuzqnbw.js";import{A as t}from"./framer-Be3hPn0e.js";import{n,t as r}from"./ArticleLayout-DhWSOcXp.js";var i,a,o=e((()=>{i=[{"@context":`https://schema.org`,"@type":`Article`,headline:`Rouler sans carte grise à son nom : les risques réels`,description:`Rouler sans carte grise à son nom : amende jusqu'à 750 €, immobilisation possible, plaques WW. Le certificat provisoire (CPI) vous couvre légalement.`,author:{"@type":`Organization`,name:`Evidence Assurances`},publisher:{"@type":`Organization`,name:`AssuTempo`,logo:{"@type":`ImageObject`,url:`https://assutempo.fr/logo.png`}},mainEntityOfPage:`https://assutempo.fr/articles/rouler-sans-carte-grise-a-son-nom`,datePublished:`2026-07-14`,dateModified:`2026-07-14`},{"@context":`https://schema.org`,"@type":`BreadcrumbList`,itemListElement:[{"@type":`ListItem`,position:1,name:`Accueil`,item:`https://assutempo.fr`},{"@type":`ListItem`,position:2,name:`Articles`,item:`https://assutempo.fr/articles`},{"@type":`ListItem`,position:3,name:`Rouler sans carte grise à son nom`,item:`https://assutempo.fr/articles/rouler-sans-carte-grise-a-son-nom`}]},{"@context":`https://schema.org`,"@type":`FAQPage`,mainEntity:[{"@type":`Question`,name:`Combien de temps peut-on rouler légalement sans carte grise à son nom ?`,acceptedAnswer:{"@type":`Answer`,text:`1 mois calendaire à partir de la date du certificat de cession, délai fixé par l'article R322-5 du code de la route. Passé ce délai, maintenir le véhicule en circulation devient une infraction.`}},{"@type":`Question`,name:`Quelle amende risque-t-on pour une carte grise pas encore à son nom ?`,acceptedAnswer:{"@type":`Answer`,text:`Une amende forfaitaire de 135 €, minorée à 90 € en paiement rapide, majorée à 375 €. Devant le tribunal, elle peut atteindre 750 €, plafond des contraventions de 4e classe (article 131-13 du code pénal), avec une immobilisation du véhicule possible.`}},{"@type":`Question`,name:`Le certificat provisoire d'immatriculation suffit-il en cas de contrôle ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui. Le CPI vaut carte grise le temps que le titre définitif soit fabriqué et expédié, pendant 1 mois dans le cas général. Il faut simplement rester dans sa période de validité.`}},{"@type":`Question`,name:`Les plaques WW permettent-elles de rouler plus longtemps ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui, dans des situations différentes du CPI classique (véhicule neuf ou importé en instance d'immatriculation) : jusqu'à 4 mois au total, en 2 périodes de 2 mois (service-public.gouv.fr).`}}]}],a={slug:`rouler-sans-carte-grise-a-son-nom`,seo:{title:`Rouler sans carte grise à son nom : les risques`,description:`Rouler sans carte grise à son nom : amende jusqu'à 750 €, immobilisation possible, plaques WW. Le certificat provisoire (CPI) vous couvre légalement.`,canonical:`https://assutempo.fr/articles/rouler-sans-carte-grise-a-son-nom`,jsonLd:i},category:`Carte grise`,readTime:`6 min`,updatedDate:`14 juillet 2026`,author:`Evidence Assurances`,headline:`Rouler sans carte grise à son nom : ce que la loi sanctionne vraiment`,cta:{href:`/carte-grise`,label:`Démarrer ma demande de carte grise`,title:`Certificat provisoire délivré sous 24 h ouvrées.`,subtitle:`Dossier vérifié avant transmission, saisie SIV par un professionnel habilité.`,suffix:`Sans rendez-vous.`},answerCapsule:{answer:`Un mois calendaire après l'achat pour immatriculer un véhicule à son nom (article R322-5 du code de la route). Passé ce délai, rouler sans certificat d'immatriculation à jour expose à une amende forfaitaire de 135 €, jusqu'à 750 € devant le tribunal, et à une immobilisation possible. Le certificat provisoire (CPI) évite ce risque immédiatement.`,facts:[{anchor:`1 mois`,text:`Délai légal pour immatriculer un véhicule à son nom après achat, à partir de la date du certificat de cession (article R322-5 du code de la route).`},{anchor:`135 € à 750 €`,text:`Amende forfaitaire (90 € minorée, 375 € majorée), jusqu'à 750 € devant le tribunal : contravention de 4e classe (article 131-13 du code pénal), immobilisation possible.`},{anchor:`4 mois maximum`,text:`Durée totale d'une plaque WW (2 périodes de 2 mois), pour un véhicule neuf ou importé en instance d'immatriculation définitive (service-public.gouv.fr).`}],updated:`14 juillet 2026`},sections:[{type:`alert`,heading:`L'essentiel`,items:[`1 mois calendaire pour immatriculer un véhicule à son nom après achat, à partir de la date du certificat de cession (article R322-5 du code de la route).`,`Passé ce délai, maintenir le véhicule en circulation est une contravention de 4e classe : 135 € d'amende forfaitaire, jusqu'à 750 € devant le tribunal (article 131-13 du code pénal), et immobilisation possible.`,`Le certificat provisoire d'immatriculation (CPI) autorise à rouler en France dès sa délivrance, pendant 1 mois dans le cas général.`,`Les plaques WW couvrent des situations différentes (véhicule neuf ou importé en instance d'immatriculation) : 4 mois maximum, en 2 périodes de 2 mois (service-public.gouv.fr).`]},{type:`text`,heading:`Rouler sans carte grise à son nom, qu'est-ce que la loi sanctionne vraiment ?`,paragraphs:[`Pas le simple fait d'avoir acheté un véhicule sans avoir encore terminé la paperasse. La loi laisse un mois calendaire, à compter du certificat de cession, pour immatriculer le véhicule à son nom (article R322-5 du code de la route). Pendant ce mois, rouler avec l'ancienne carte grise barrée et le certificat de cession en main n'a rien d'irrégulier, à condition que le véhicule reste assuré.`,`Ce que la loi punit, c'est le fait de dépasser ce délai sans solution, en maintenant le véhicule en circulation. Beaucoup confondent les deux : ne pas avoir sa carte grise à jour un 15e jour n'est pas un problème en soi, ne pas l'avoir un 45e jour, sans certificat provisoire pour couvrir l'attente, en est un.`]},{type:`table`,heading:`Quel est le risque réel selon la situation ?`,intro:`Le contrôle routier ne regarde pas la même chose selon le moment où il tombe. Voici les quatre cas de figure les plus fréquents.`,columns:[`Situation`,`Statut légal`,`Risque en cas de contrôle`],rows:[[`Moins d'1 mois après l'achat, certificat de cession en main`,`Toléré, délai légal en cours`,`Aucun, si le véhicule est assuré et le certificat de cession présentable`],[`Certificat provisoire d'immatriculation (CPI) en cours de validité`,`En règle`,`Aucun : le CPI vaut carte grise le temps que le titre définitif arrive`],[`Plus d'1 mois après l'achat, sans CPI ni carte grise à son nom`,`Infraction, contravention de 4e classe`,`135 € d'amende forfaitaire (90 € minorée, 375 € majorée), jusqu'à 750 € devant le tribunal, immobilisation possible`],[`Plaque WW expirée, au-delà de 4 mois`,`Infraction, circulation interdite`,`Amende pour défaut d'immatriculation valide, immobilisation possible`]],note:`Montants et délais : service-public.gouv.fr, article R322-5 du code de la route et article 131-13 du code pénal.`},{type:`checklist`,heading:`Quels documents évitent une infraction involontaire ?`,intro:`Un dossier complet dès le premier jour évite de basculer, sans le vouloir, dans l'infraction :`,items:[`Le certificat de cession (Cerfa 15776) ou l'ancienne carte grise barrée, datée et signée`,`Le certificat provisoire d'immatriculation (CPI), dès que le dossier est déposé`,`L'attestation d'assurance, obligatoire dès le premier trajet`,`Un justificatif de domicile de moins de 6 mois et une pièce d'identité en cours de validité`],relatedLink:{text:`Obtenir un certificat provisoire d'immatriculation immédiat`,href:`/articles/carte-grise-urgence-cpi-immediat`}},{type:`text`,heading:`Le certificat provisoire, la vraie porte de sortie légale`,paragraphs:[`Le CPI est édité dès la saisie du dossier dans le système d'immatriculation des véhicules (SIV) par un professionnel habilité par le Ministère de l'Intérieur. Sur assutempo.fr, la demande est traitée via Certimat, qui vérifie le dossier sous 24 h ouvrées puis met en relation avec un professionnel habilité pour la saisie, ou transmet le dossier à l'Agence Nationale des Titres Sécurisés (ANTS, France Titres). Certimat est un intermédiaire technologique : la plateforme n'est pas elle-même habilitée au SIV, et ne délivre aucun titre.`,`Un point souvent mal compris : le CPI n'attend pas la carte grise définitive pour exister, il la précède. Dès sa délivrance, il autorise à circuler en France, plaque définitive du véhicule déjà attribuée, pendant que le titre papier suit son propre circuit de fabrication chez France Titres.`],relatedLink:{text:`Démarrer ma demande de carte grise`,href:`/carte-grise`}},{type:`text`,heading:`Et l'assurance, pendant cette période ?`,paragraphs:[`L'obligation d'assurance ne dépend jamais du statut de la carte grise. La responsabilité civile doit couvrir le véhicule dès le premier trajet, carte grise à l'ancien nom, certificat de cession seul, ou CPI en poche. Rouler sans assurance est une infraction distincte, plus lourde : jusqu'à 3 750 € d'amende pénale (Code de la route, article L324-2), en plus des risques liés à la carte grise.`,`Une assurance temporaire AssuTempo (assutempo.fr) délivre une attestation par email en 5 minutes, avec le certificat de cession, le numéro VIN ou le CPI, sans attendre que la carte grise soit finalisée à votre nom. De quoi couvrir les deux fronts, assurance et immatriculation, sans laisser de trou dans la légalité pendant le mois de transition.`],relatedLink:{text:`Assurer un véhicule le temps d'obtenir sa carte grise`,href:`/tarification`}},{type:`text`,heading:`Que risque-t-on vraiment si on laisse traîner, sans CPI ni démarche ?`,paragraphs:[`Le cas le plus fréquent n'est pas le contrôle routier de routine, plutôt rare sur ce point précis, mais l'accident. Un sinistre révèle immédiatement une situation irrégulière : véhicule non assuré, non immatriculé au bon nom, parfois les deux à la fois. C'est à ce moment que les deux infractions se cumulent, avec des conséquences plus lourdes qu'un simple rappel à l'ordre.`,`Le réflexe honnête reste le même dans presque tous les cas : traiter les deux sujets, assurance et carte grise, dès la sortie du parking, plutôt que de miser sur la discrétion d'un trajet du quotidien.`]}],faqItems:[{q:`Combien de temps peut-on rouler légalement sans carte grise à son nom ?`,a:`1 mois calendaire à partir de la date du certificat de cession, délai fixé par l'article R322-5 du code de la route. Passé ce délai, maintenir le véhicule en circulation devient une infraction.`},{q:`Quelle amende risque-t-on pour une carte grise pas encore à son nom ?`,a:`Une amende forfaitaire de 135 €, minorée à 90 € en paiement rapide, majorée à 375 €. Devant le tribunal, elle peut atteindre 750 €, plafond des contraventions de 4e classe (article 131-13 du code pénal), avec une immobilisation du véhicule possible.`},{q:`Le certificat provisoire d'immatriculation suffit-il en cas de contrôle ?`,a:`Oui. Le CPI vaut carte grise le temps que le titre définitif soit fabriqué et expédié, pendant 1 mois dans le cas général. Il faut simplement rester dans sa période de validité.`},{q:`Les plaques WW permettent-elles de rouler plus longtemps ?`,a:`Oui, dans des situations différentes du CPI classique (véhicule neuf ou importé en instance d'immatriculation) : jusqu'à 4 mois au total, en 2 périodes de 2 mois (service-public.gouv.fr).`}]}}));function s(){return(0,c.jsx)(r,{data:a})}var c;e((()=>{n(),o(),c=t()}))();export{s as default};